    private LegacyItemFixtures() {}
    public record Item(String label, String rawLore, List<Component> lore, String rawName, Component name, boolean currentOwnership) {
        @Override public String toString() { return label; }
    }
    public static List<Item> items() {
        List<Item> result = new ArrayList<>();
        for (JsonElement value : JsonParser.parseString(SNAPSHOTS).getAsJsonArray()) {
            JsonObject item = value.getAsJsonObject(), raw = item.getAsJsonObject("raw");
            List<Component> lore = new ArrayList<>();
            for (JsonElement line : item.getAsJsonArray("lore")) lore.add(component(line));
            result.add(new Item(item.get("label").getAsString(), string(raw, "raw_lore_markup"), List.copyOf(lore),
                    string(raw, "raw_name_markup"), item.get("name").isJsonNull() ? null : component(item.get("name")),
                    raw.has("owned_lore_version")));
        }
        return List.copyOf(result);
    }
    private static String string(JsonObject object, String key) { return object.has(key) ? object.get(key).getAsString() : ""; }
    private static boolean flag(JsonObject j, String key) {
        JsonPrimitive p = j.getAsJsonPrimitive(key);
        return p.isNumber() ? p.getAsInt() != 0 : p.getAsBoolean();
    }
    private static Component component(JsonElement value) {
        if (value.isJsonPrimitive()) return Component.literal(value.getAsString());
        JsonObject j = value.getAsJsonObject();
        MutableComponent c = Component.literal(string(j, "text"));
        Style s = Style.EMPTY;
        if (j.has("color")) s = s.withColor(TextColor.fromRgb(Integer.parseInt(j.get("color").getAsString().substring(1), 16)));
        if (j.has("bold")) s = s.withBold(flag(j, "bold"));
        if (j.has("italic")) s = s.withItalic(flag(j, "italic"));
        if (j.has("underlined")) s = s.withUnderlined(flag(j, "underlined"));
        if (j.has("strikethrough")) s = s.withStrikethrough(flag(j, "strikethrough"));
        if (j.has("obfuscated")) s = s.withObfuscated(flag(j, "obfuscated"));
        if (j.has("insertion")) s = s.withInsertion(string(j, "insertion"));
        c.setStyle(s);
        if (j.has("extra")) for (JsonElement child : j.getAsJsonArray("extra")) c.append(component(child));
        return c;
    }
